import java.util.List;
import sailpoint.object.AuditEvent;

String trim(String s, int max) {
    if (s == null) return null;
    return s.length() <= max ? s : s.substring(0, max - 3) + "...";
}

String auditAction;
if ("DENIED".equals(workflowResult)) auditAction = "EmergencyIdentityDenied";
else if ("Enable".equalsIgnoreCase(requestedAction)) auditAction = "EmergencyIdentityEnable";
else auditAction = "EmergencyIdentityDisable";

String detailText = (details == null) ? "" : details.toString();

AuditEvent ev = new AuditEvent();
ev.setAction(auditAction);
ev.setSource(launcher);
ev.setTarget(identityName);
ev.setApplication("IdentityIQ");
ev.setString1(workflowResult);
ev.setString2(trim(justification, 450));
ev.setString3(String.valueOf(previousValue) + " -> " + String.valueOf(newValue));
ev.setString4(trim(detailText, 450));
ev.setAttribute("requestedAction", requestedAction);
ev.setAttribute("accounts", details);
ev.setAttribute("workflowCaseId", workflowCaseId);
context.saveObject(ev);
context.commitTransaction();

log.warn("Emergency Identity: " + auditAction + " requestor=" + launcher + " target=" + identityName
         + " action=" + requestedAction + " result=" + workflowResult
         + " emergencyDisable=" + previousValue + "->" + newValue + " accounts=" + detailText);
return ev.getId();
